using Mutagen.Bethesda.Plugins.Binary.Headers;
using Mutagen.Bethesda.Plugins.Binary.Overlay;
using Mutagen.Bethesda.Plugins.Binary.Streams;
using Mutagen.Bethesda.Plugins.Meta;
using Mutagen.Bethesda.Plugins.Records;
using Mutagen.Bethesda.Starfield;
using Shouldly;
using Xunit;
using static Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield.StarfieldTestRecords;

namespace Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield;

// Raw or signature-named fields of five object records get xEdit's names and types (wbDefinitionsSF1):
// - MRPH: TMPP Target Morph Path, TCMP Target Chargen Morph Path; MOBC is Base Vertex Color (a byte) and 3 unused
//   bytes (998 MOBC, all 4 bytes: FF 879, C0 107, BF 7, 00 5; bytes 1-3 always 0).
// - MSTT: DATA is Mass Override Flags (bit 1 Use Mass Override, bit 2 Scale; values 04, 06, 02, 00; MSMO is on
//   exactly the 61 with bit 1), MSLS Looping Sound, MSMO Mass Override Value.
// - PDCL: DATA is Min/Max Width, Min/Max Height, Depth and Cutoff Angle (706 PDCL, all 24 bytes).
// - TRNS: BNAM is the Basis enum (World Bound 468, Object Origin 244), ENAM the Color Mode Flags (0 or 1).
// - TXST: ODTY is the float Dirtiness Scale (all 0), TX00/01/08/09/17/19 are Diffuse, Normal/Gloss, Metal, Rough,
//   AO, Opacity; DODT is the Decal data (24 bytes in all 20; the existing Decal object).
// Each test reads a whole record from Starfield.esm with both readers and writes it back byte for byte.
public class ObjectRecordFieldNameTests
{
    private static void WritesBack(Action<MutagenWriter> write, string hex)
    {
        var written = GameConstants.Starfield.MajorRecord(Write(write));
        written.Content.ToArray().ShouldBe(Hex(hex));
    }

    // MORPH_Child_Head_CoraCoe (0059FA:Starfield.esm)
    private const string MorphTarget = "4544494419004D4F5250485F4368696C645F486561645F436F7261436F6500544D50502D004D65736865735C4D6F727068735C4368696C645C486561645F436F7261436F655C506572666F726D616E6365004D4F42430400BF000000";
    // MORPH_Clothes_Hazmat_Suit_01_Decals_F (08AE12:Starfield.esm)
    private const string MorphChargen = "";
    // ThermalVentSmoke (001621:Starfield.esm)
    private const string VentSmoke = "";
    // SMOD_Docker_Stroud_Connect-Pro_Port (1E0527:Starfield.esm)
    private const string DockerPort = "";
    // proj_Decal_AKWallPaintWhite (001DA2:Starfield.esm)
    private const string WallPaint = "";
    // Outpost_GlobeEarth01 (02A76E:Starfield.esm)
    private const string Globe = "4544494415004F7574706F73745F476C6F62654561727468303100444154412400000000246666663F000080BE321290BE00000000000000000000803F000080BF0000803F424E414D010001454E414D040000000000";
    // Inv_Guns_Workbench3D_05 (057195:Starfield.esm)
    private const string Workbench = "454449441800496E765F47756E735F576F726B62656E636833445F3035004441544124000AD7A33C0AD7A3BC0AD7A33C31AFC04000000000920A86400000803F000020C1000020C1424E414D010001454E414D040001000000";
    // DecalSubtleGrungeFootprints02 (061738:Starfield.esm)
    private const string Footprints = "";

    [Fact]
    public void MorphableObject_Paths_BaseVertexColor()
    {
        foreach (var mrph in ReadBoth<IMorphableObjectGetter>(Record("MRPH", Hex(MorphTarget)), f => MorphableObject.CreateFromBinary(f), (s, p) => MorphableObjectBinaryOverlay.MorphableObjectFactory(s, p)))
        {
            mrph.TargetMorphPath.ShouldBe(@"Meshes\Morphs\Child\Head_CoraCoe\Performance");
            mrph.TargetChargenMorphPath.ShouldBeNull();
            mrph.BaseVertexColor.ShouldBe((byte)0xBF);
            WritesBack(w => mrph.WriteToBinary(w), MorphTarget);
        }
        foreach (var mrph in ReadBoth<IMorphableObjectGetter>(Record("MRPH", Hex(MorphChargen)), f => MorphableObject.CreateFromBinary(f), (s, p) => MorphableObjectBinaryOverlay.MorphableObjectFactory(s, p)))
        {
            mrph.TargetChargenMorphPath.ShouldNotBeNull().ShouldStartWith(@"Meshes\Morphs\Clothes\Outfit_Hazmat_Suit_01\");
            mrph.BaseVertexColor.ShouldBe((byte)0xC0);
            WritesBack(w => mrph.WriteToBinary(w), MorphChargen);
        }
    }

    [Fact]
    public void MoveableStatic_MassOverride_LoopingSound()
    {
        foreach (var mstt in ReadBoth<IMoveableStaticGetter>(Record("MSTT", Hex(VentSmoke)), f => MoveableStatic.CreateFromBinary(f), (s, p) => MoveableStaticBinaryOverlay.MoveableStaticFactory(s, p)))
        {
            mstt.MassOverrideFlags.ShouldBe(MoveableStatic.MassOverrideFlag.Scale);
            mstt.LoopingSound.ShouldNotBeNull();
            mstt.MassOverrideValue.ShouldBeNull();
            WritesBack(w => mstt.WriteToBinary(w), VentSmoke);
        }
        foreach (var mstt in ReadBoth<IMoveableStaticGetter>(Record("MSTT", Hex(DockerPort)), f => MoveableStatic.CreateFromBinary(f), (s, p) => MoveableStaticBinaryOverlay.MoveableStaticFactory(s, p)))
        {
            mstt.MassOverrideFlags.ShouldBe(MoveableStatic.MassOverrideFlag.UseMassOverride | MoveableStatic.MassOverrideFlag.Scale);
            mstt.MassOverrideValue.ShouldBe(1000f);
            WritesBack(w => mstt.WriteToBinary(w), DockerPort);
        }
    }

    [Fact]
    public void ProjectedDecal_Data()
    {
        foreach (var pdcl in ReadBoth<IProjectedDecalGetter>(Record("PDCL", Hex(WallPaint)), f => ProjectedDecal.CreateFromBinary(f), (s, p) => ProjectedDecalBinaryOverlay.ProjectedDecalFactory(s, p)))
        {
            pdcl.MinWidth.ShouldBe(4f);
            pdcl.MaxWidth.ShouldBe(4f);
            pdcl.MinHeight.ShouldBe(4f);
            pdcl.MaxHeight.ShouldBe(4f);
            pdcl.Depth.ShouldBe(10f);
            pdcl.CutoffAngle.ShouldBe(72.54f, 0.001f);
            WritesBack(w => pdcl.WriteToBinary(w), WallPaint);
        }
    }

    [Fact]
    public void Transform_BasisAndColorMode()
    {
        foreach (var trns in ReadBoth<ITransformGetter>(Record("TRNS", Hex(Globe)), f => Transform.CreateFromBinary(f), (s, p) => TransformBinaryOverlay.TransformFactory(s, p)))
        {
            trns.Basis.ShouldBe(Transform.BasisType.ObjectOrigin);
            trns.ColorModeFlags.ShouldBe((Transform.ColorModeFlag)0);
            WritesBack(w => trns.WriteToBinary(w), Globe);
        }
        foreach (var trns in ReadBoth<ITransformGetter>(Record("TRNS", Hex(Workbench)), f => Transform.CreateFromBinary(f), (s, p) => TransformBinaryOverlay.TransformFactory(s, p)))
        {
            trns.ColorModeFlags.ShouldBe(Transform.ColorModeFlag.Normal);
            WritesBack(w => trns.WriteToBinary(w), Workbench);
        }
    }

    [Fact]
    public void TextureSet_TexturesAndDecal()
    {
        foreach (var txst in ReadBoth<ITextureSetGetter>(Record("TXST", Hex(Footprints)), f => TextureSet.CreateFromBinary(f), (s, p) => TextureSetBinaryOverlay.TextureSetFactory(s, p)))
        {
            txst.DirtinessScale.ShouldBe(0f);
            txst.Diffuse.ShouldBe(@"Decals\Subtle\DecalSubtleGrungeFootprints02_color.dds");
            txst.NormalGloss.ShouldBe(@"Shared\Default_normal.dds");
            txst.Metal.ShouldBe(@"Shared\default_metal.dds");
            txst.Rough.ShouldBe(@"Shared\default_rough.dds");
            txst.AmbientOcclusion.ShouldBeNull();
            txst.Opacity.ShouldBe(@"Decals\Subtle\DecalSubtleGrungeFootprints02_opacity.dds");
            var decal = txst.Decal.ShouldNotBeNull();
            decal.MinWidth.ShouldBe(4f);
            decal.MaxWidth.ShouldBe(4f);
            decal.MinHeight.ShouldBe(2f);
            decal.MaxHeight.ShouldBe(4f);
            decal.Depth.ShouldBe(0.75f);
            decal.Alpha.ShouldBe(1f);
            WritesBack(w => txst.WriteToBinary(w), Footprints);
        }
    }
}
